import{_ as e,c as t,o as a,a0 as i}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Plantilla de diario de entrenamiento","description":"","frontmatter":{},"headers":[],"relativePath":"es/diary-template.md","filePath":"es/diary-template.md"}');const r=e({name:"es/diary-template.md"},[["render",function(e,o,r,n,s,l){return a(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="plantilla-de-diario-de-entrenamiento" tabindex="-1">Plantilla de diario de entrenamiento <a class="header-anchor" href="#plantilla-de-diario-de-entrenamiento" aria-label="Permalink to &quot;Plantilla de diario de entrenamiento&quot;">​</a></h1><h2 id="como-utilizar-esta-plantilla" tabindex="-1">Cómo utilizar esta plantilla <a class="header-anchor" href="#como-utilizar-esta-plantilla" aria-label="Permalink to &quot;Cómo utilizar esta plantilla&quot;">​</a></h2><p>Un diario de entrenamiento es tu registro personal de práctica, progreso y aprendizaje. Te ayuda a registrar lo que funciona, identificar patrones y acelerar la mejora. Copia las siguientes secciones en tu formato preferido (Word, Documentos de Google, Excel, Hojas de Cálculo de Google o un bloc de notas).</p><div class="tip custom-block"><p class="custom-block-title">El poder de la reflexión</p><p><strong>Lo que se mide se mejora. Lo que se reflexiona se domina.</strong> Un diario de entrenamiento transforma la práctica aleatoria en desarrollo deliberado.</p></div><h2 id="plantilla-de-entrada-de-entrenamiento-diario" tabindex="-1">Plantilla de entrada de entrenamiento diario <a class="header-anchor" href="#plantilla-de-entrada-de-entrenamiento-diario" aria-label="Permalink to &quot;Plantilla de entrada de entrenamiento diario&quot;">​</a></h2><h3 id="copie-esta-seccion-para-cada-sesion-de-capacitacion" tabindex="-1">Copie esta sección para cada sesión de capacitación <a class="header-anchor" href="#copie-esta-seccion-para-cada-sesion-de-capacitacion" aria-label="Permalink to &quot;Copie esta sección para cada sesión de capacitación&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Time:</strong> ________ to ________ <strong>Duration:</strong> ________ minutes <strong>Location:</strong> ________ <strong>Terrain:</strong> Hard / Medium / Soft / Mixed <strong>Weather:</strong> Sunny / Cloudy / Windy / Rain</p><h3 id="training-partners" tabindex="-1">Training Partners <a class="header-anchor" href="#training-partners" aria-label="Permalink to &quot;Training Partners&quot;">​</a></h3><ul><li></li><li></li><li></li></ul><h3 id="today-s-intention" tabindex="-1">Today&#39;s Intention <a class="header-anchor" href="#today-s-intention" aria-label="Permalink to &quot;Today&#39;s Intention&quot;">​</a></h3><p>(What was my main focus for this session?)</p><hr><h3 id="practica-tecnica" tabindex="-1">Práctica técnica <a class="header-anchor" href="#practica-tecnica" aria-label="Permalink to &quot;Práctica técnica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Habilidad practicada</th><th>Repeticiones/Tiempo</th><th>Tasa de éxito</th><th>Notas</th></tr></thead><tbody><tr><td><strong>Señalando</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Disparos</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Lectura del terreno</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Selección de disparos</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="¿que-funciono-bien" tabindex="-1">¿Qué funcionó bien? <a class="header-anchor" href="#¿que-funciono-bien" aria-label="Permalink to &quot;¿Qué funcionó bien?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="¿que-necesita-mejorar" tabindex="-1">¿Qué necesita mejorar? <a class="header-anchor" href="#¿que-necesita-mejorar" aria-label="Permalink to &quot;¿Qué necesita mejorar?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="informacion-clave" tabindex="-1">Información clave <a class="header-anchor" href="#informacion-clave" aria-label="Permalink to &quot;Información clave&quot;">​</a></h3><p>(Un aprendizaje principal de hoy)</p><hr><h3 id="mental-game" tabindex="-1">Mental Game <a class="header-anchor" href="#mental-game" aria-label="Permalink to &quot;Mental Game&quot;">​</a></h3><p><strong>Energy Level (1-10):</strong> _____ <strong>Focus Quality (1-10):</strong> _____ <strong>Confidence (1-10):</strong> _____</p><p><strong>Mental Challenges Today:</strong></p><p><strong>How I Handled Them:</strong></p><p><strong>Mental Technique Practiced:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Other: ________</li></ul><hr><h3 id="condicion-fisica" tabindex="-1">Condición física <a class="header-anchor" href="#condicion-fisica" aria-label="Permalink to &quot;Condición física&quot;">​</a></h3><p><strong>Sensación corporal (1-10):</strong> _____ <strong>Cualquier dolor/malestar:</strong> _____ <strong>Nivel de fatiga (1-10):</strong> _____</p><p><strong>Notas físicas:</strong></p><hr><h3 id="tomorrow-s-focus" tabindex="-1">Tomorrow&#39;s Focus <a class="header-anchor" href="#tomorrow-s-focus" aria-label="Permalink to &quot;Tomorrow&#39;s Focus&quot;">​</a></h3><p>(Based on today, what will I work on next session?)</p><hr><h2 id="plantilla-de-inscripcion-para-competicion-partido" tabindex="-1">Plantilla de inscripción para competición/partido <a class="header-anchor" href="#plantilla-de-inscripcion-para-competicion-partido" aria-label="Permalink to &quot;Plantilla de inscripción para competición/partido&quot;">​</a></h2><h3 id="copiar-esta-seccion-para-cada-competencia" tabindex="-1">Copiar esta sección para cada competencia <a class="header-anchor" href="#copiar-esta-seccion-para-cada-competencia" aria-label="Permalink to &quot;Copiar esta sección para cada competencia&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Tournament:</strong> ________ <strong>Format:</strong> Triples / Doubles / Singles <strong>Team:</strong> ________</p><h3 id="pre-competition" tabindex="-1">Pre-Competition <a class="header-anchor" href="#pre-competition" aria-label="Permalink to &quot;Pre-Competition&quot;">​</a></h3><p><strong>Sleep Quality (1-10):</strong> _____ <strong>Nutrition:</strong> _____ <strong>Mental State (1-10):</strong> _____ <strong>Physical Warm-up:</strong> Yes / No <strong>Mental Warm-up:</strong> Yes / No</p><hr><h3 id="resultados-del-partido" tabindex="-1">Resultados del partido <a class="header-anchor" href="#resultados-del-partido" aria-label="Permalink to &quot;Resultados del partido&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ronda</th><th>Rival</th><th>Puntuación</th><th>Resultado</th><th>Momentos clave</th></tr></thead><tbody><tr><td><strong>1</strong></td><td></td><td></td><td>An / L</td><td></td></tr><tr><td><strong>2</strong></td><td></td><td></td><td>An / L</td><td></td></tr><tr><td><strong>3</strong></td><td></td><td></td><td>An / L</td><td></td></tr><tr><td><strong>4</strong></td><td></td><td></td><td>G / L</td><td></td></tr></tbody></table><p><strong>Colocación final:</strong> _____</p><hr><h3 id="performance-analysis" tabindex="-1">Performance Analysis <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;Performance Analysis&quot;">​</a></h3><p><strong>Technical Performance (1-10):</strong> _____ <strong>Mental Performance (1-10):</strong> _____ <strong>Tactical Decisions (1-10):</strong> _____ <strong>Team Communication (1-10):</strong> _____</p><h3 id="what-i-did-well" tabindex="-1">What I Did Well <a class="header-anchor" href="#what-i-did-well" aria-label="Permalink to &quot;What I Did Well&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="what-cost-me-points" tabindex="-1">What Cost Me Points <a class="header-anchor" href="#what-cost-me-points" aria-label="Permalink to &quot;What Cost Me Points&quot;">​</a></h3><ol><li></li><li></li></ol><h2 id="monthly-summary-template" tabindex="-1">Monthly Summary Template <a class="header-anchor" href="#monthly-summary-template" aria-label="Permalink to &quot;Monthly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Mes:</strong> ________ <strong>Año:</strong> ________</p><h3 id="estadisticas-mensuales" tabindex="-1">Estadísticas mensuales <a class="header-anchor" href="#estadisticas-mensuales" aria-label="Permalink to &quot;Estadísticas mensuales&quot;">​</a></h3><p><strong>Total de horas de capacitación:</strong> _____ <strong>Total de sesiones:</strong> _____ <strong>Concursos en los que participó:</strong> _____ <strong>Tasa de victorias:</strong> _____%</p><h3 id="progreso-tecnico" tabindex="-1">Progreso técnico <a class="header-anchor" href="#progreso-tecnico" aria-label="Permalink to &quot;Progreso técnico&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Habilidad</th><th>Inicio de mes</th><th>Fin de mes</th><th>Mejora</th></tr></thead><tbody><tr><td><strong>Precisión de puntería</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Consistencia en el tiro</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Adaptación al terreno</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Selección de disparos</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="progreso-del-juego-mental" tabindex="-1">Progreso del juego mental <a class="header-anchor" href="#progreso-del-juego-mental" aria-label="Permalink to &quot;Progreso del juego mental&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Área</th><th>Inicio de mes</th><th>Fin de mes</th><th>Mejora</th></tr></thead><tbody><tr><td><strong>Gestión de la presión</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Calidad de enfoque</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Confianza</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Uso del Coach Interno</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="aspectos-destacados-del-mes" tabindex="-1">Aspectos destacados del mes <a class="header-anchor" href="#aspectos-destacados-del-mes" aria-label="Permalink to &quot;Aspectos destacados del mes&quot;">​</a></h3><p><strong>Mejor sesión de entrenamiento:</strong></p><p><strong>Mejor actuación en competición:</strong></p><p><strong>El mayor avance:</strong></p><p><strong>Aprendizaje más valioso:</strong></p><h3 id="desafios-superados" tabindex="-1">Desafíos superados <a class="header-anchor" href="#desafios-superados" aria-label="Permalink to &quot;Desafíos superados&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="desafios-actuales" tabindex="-1">Desafíos actuales <a class="header-anchor" href="#desafios-actuales" aria-label="Permalink to &quot;Desafíos actuales&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="prioridades-del-proximo-mes" tabindex="-1">Prioridades del próximo mes <a class="header-anchor" href="#prioridades-del-proximo-mes" aria-label="Permalink to &quot;Prioridades del próximo mes&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr><h2 id="specific-practice-tracking-templates" tabindex="-1">Specific Practice Tracking Templates <a class="header-anchor" href="#specific-practice-tracking-templates" aria-label="Permalink to &quot;Specific Practice Tracking Templates&quot;">​</a></h2><h3 id="pointing-practice-log" tabindex="-1">Pointing Practice Log <a class="header-anchor" href="#pointing-practice-log" aria-label="Permalink to &quot;Pointing Practice Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Distance</th><th>Terrain</th><th>Attempts</th><th>Within 10cm</th><th>Within 20cm</th><th>Within 50cm</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions:</strong></p><ul><li>Track pointing accuracy at different distances (6m, 7m, 8m, 9m, 10m)</li><li>Record terrain type (hard, medium, soft)</li><li>Count successes in each distance range</li><li>Calculate success rate over time</li></ul><hr><h3 id="registro-de-practicas-de-tiro" tabindex="-1">Registro de prácticas de tiro <a class="header-anchor" href="#registro-de-practicas-de-tiro" aria-label="Permalink to &quot;Registro de prácticas de tiro&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fecha</th><th>Tipo de objetivo</th><th>Distancia</th><th>Intentos</th><th>Impactos directos</th><th>Carreau</th><th>Desplazamiento</th><th>Notas</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Tipos de objetivos:</strong></p><ul><li>Pelota estática</li><li>Balón contra cochonnet</li><li>Pelota en racimo</li><li>Objetivo móvil (avanzado)</li></ul><hr><h3 id="mental-training-log" tabindex="-1">Mental Training Log <a class="header-anchor" href="#mental-training-log" aria-label="Permalink to &quot;Mental Training Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Technique Practiced</th><th>Duration</th><th>Situation</th><th>Effectiveness (1-10)</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Techniques:</strong></p><ul><li>3-Breath Reset</li><li>Inner Coach Reframe</li><li>Visualization</li><li>Mindfulness Practice</li><li>Pre-shot Routine</li><li>Pressure Simulation</li></ul><hr><h2 id="entrada-diaria-rapida-simplificada" tabindex="-1">Entrada diaria rápida (simplificada) <a class="header-anchor" href="#entrada-diaria-rapida-simplificada" aria-label="Permalink to &quot;Entrada diaria rápida (simplificada)&quot;">​</a></h2><h3 id="para-dias-ocupados-copia-esta-plantilla-minimalista" tabindex="-1">Para días ocupados: copia esta plantilla minimalista <a class="header-anchor" href="#para-dias-ocupados-copia-esta-plantilla-minimalista" aria-label="Permalink to &quot;Para días ocupados: copia esta plantilla minimalista&quot;">​</a></h3><hr><p><strong>Date:</strong> ________</p><p><strong>Trained:</strong> Yes / No <strong>Duration:</strong> _____ min <strong>Focus:</strong> ________ <strong>Energy (1-10):</strong> _____ <strong>Quality (1-10):</strong> _____</p><p><strong>One Win:</strong></p><p><strong>One Learning:</strong></p><p><strong>Tomorrow&#39;s Focus:</strong></p><hr><h2 id="sugerencias-para-la-reflexion" tabindex="-1">Sugerencias para la reflexión <a class="header-anchor" href="#sugerencias-para-la-reflexion" aria-label="Permalink to &quot;Sugerencias para la reflexión&quot;">​</a></h2><p>Utilice estas indicaciones para profundizar en las entradas de su diario:</p><h3 id="despues-del-entrenamiento" tabindex="-1">Después del entrenamiento <a class="header-anchor" href="#despues-del-entrenamiento" aria-label="Permalink to &quot;Después del entrenamiento&quot;">​</a></h3><ol><li>¿Qué me sorprendió hoy?</li><li>¿Cuándo me sentí más seguro?</li><li>¿Cuándo tuve dificultades? ¿Por qué?</li><li>¿Qué haría diferente?</li><li>¿De qué estoy agradecido de esta sesión?</li></ol><h3 id="despues-de-la-competicion" tabindex="-1">Después de la competición <a class="header-anchor" href="#despues-de-la-competicion" aria-label="Permalink to &quot;Después de la competición&quot;">​</a></h3><ol><li>¿Qué aprendí sobre mí hoy?</li><li>¿Cómo manejé la presión?</li><li>¿Qué diría mi Coach Interno sobre mi desempeño?</li><li>¿Qué practicaré de manera diferente a partir de hoy?</li><li>¿De qué estoy orgulloso, independientemente del resultado?</li></ol><h3 id="reflexion-semanal" tabindex="-1">Reflexión semanal <a class="header-anchor" href="#reflexion-semanal" aria-label="Permalink to &quot;Reflexión semanal&quot;">​</a></h3><ol><li>¿Qué patrón estoy notando en mi práctica?</li><li>¿Estoy practicando lo que me cuesta hacer en la competición?</li><li>¿Está mejorando mi juego mental?</li><li>¿Estoy disfrutando el proceso?</li><li>¿Qué necesita cambiar la próxima semana?</li></ol><h3 id="reflexion-mensual" tabindex="-1">Reflexión mensual <a class="header-anchor" href="#reflexion-mensual" aria-label="Permalink to &quot;Reflexión mensual&quot;">​</a></h3><ol><li>¿Estoy más cerca de mis objetivos que el mes pasado?</li><li>¿Qué funciona en mi enfoque de entrenamiento?</li><li>¿Qué no está funcionando?</li><li>¿Necesito ajustar mis objetivos?</li><li>¿Qué quiero recordar de este mes?</li></ol><hr><h2 id="tips-for-effective-diary-keeping" tabindex="-1">Tips for Effective Diary Keeping <a class="header-anchor" href="#tips-for-effective-diary-keeping" aria-label="Permalink to &quot;Tips for Effective Diary Keeping&quot;">​</a></h2><h3 id="_1-write-immediately-after-training" tabindex="-1">1. Write Immediately After Training <a class="header-anchor" href="#_1-write-immediately-after-training" aria-label="Permalink to &quot;1. Write Immediately After Training&quot;">​</a></h3><p><strong>Why:</strong> Details are fresh, emotions are real, insights are clear</p><p><strong>How:</strong> Keep diary in your bag, set 10 minutes aside after each session</p><h3 id="_2-be-honest-not-perfect" tabindex="-1">2. Be Honest, Not Perfect <a class="header-anchor" href="#_2-be-honest-not-perfect" aria-label="Permalink to &quot;2. Be Honest, Not Perfect&quot;">​</a></h3><p><strong>Don&#39;t:</strong> Write what you think you should write <strong>Do:</strong> Write what actually happened and how you really felt</p><h3 id="_3-focus-on-process-not-just-results" tabindex="-1">3. Focus on Process, Not Just Results <a class="header-anchor" href="#_3-focus-on-process-not-just-results" aria-label="Permalink to &quot;3. Focus on Process, Not Just Results&quot;">​</a></h3><p><strong>Don&#39;t:</strong> &quot;Missed 7 out of 10 shots - terrible&quot; <strong>Do:</strong> &quot;Missed 7 out of 10 shots - noticed I was rushing my routine, will slow down next time&quot;</p><h3 id="_4-look-for-patterns" tabindex="-1">4. Look for Patterns <a class="header-anchor" href="#_4-look-for-patterns" aria-label="Permalink to &quot;4. Look for Patterns&quot;">​</a></h3><p>Review your diary weekly to spot:</p><ul><li>Recurring technical issues</li><li>Mental game patterns</li><li>Energy/performance correlations</li><li>What conditions you perform best in</li></ul><h3 id="_5-celebrate-progress" tabindex="-1">5. Celebrate Progress <a class="header-anchor" href="#_5-celebrate-progress" aria-label="Permalink to &quot;5. Celebrate Progress&quot;">​</a></h3><p><strong>Every month:</strong> Read entries from 3 months ago <strong>Notice:</strong> How much you&#39;ve improved <strong>Acknowledge:</strong> The work you&#39;ve put in</p><hr><h2 id="diario-digital-vs-diario-en-papel" tabindex="-1">Diario digital vs. diario en papel <a class="header-anchor" href="#diario-digital-vs-diario-en-papel" aria-label="Permalink to &quot;Diario digital vs. diario en papel&quot;">​</a></h2><h3 id="digital-documentos-hojas-de-calculo-de-google-notion-aplicaciones" tabindex="-1">Digital (Documentos/Hojas de cálculo de Google, Notion, Aplicaciones) <a class="header-anchor" href="#digital-documentos-hojas-de-calculo-de-google-notion-aplicaciones" aria-label="Permalink to &quot;Digital (Documentos/Hojas de cálculo de Google, Notion, Aplicaciones)&quot;">​</a></h3><p><strong>Ventajas:</strong></p><ul><li>Fácil búsqueda de entradas anteriores</li><li>Puede agregar fotos/videos</li><li>Sellos de fecha automáticos</li><li>Puede compartir con el entrenador.</li><li>Siempre accesible en el teléfono</li></ul><p><strong>Desventajas:</strong></p><ul><li>Tiempo frente a la pantalla</li><li>Puede sentirse impersonal</li><li>Distracciones de las notificaciones</li></ul><p><strong>Ideal para:</strong> Seguimiento de estadísticas detalladas, análisis de patrones a largo plazo</p><h3 id="papel-cuaderno-plantillas-impresas" tabindex="-1">Papel (Cuaderno, Plantillas Impresas) <a class="header-anchor" href="#papel-cuaderno-plantillas-impresas" aria-label="Permalink to &quot;Papel (Cuaderno, Plantillas Impresas)&quot;">​</a></h3><p><strong>Ventajas:</strong></p><ul><li>Conexión táctil y personal</li><li>Sin distracciones</li><li>Diagramas fáciles de esbozar</li><li>Ritual satisfactorio</li><li>Mejor para la reflexión</li></ul><p><strong>Desventajas:</strong> -Puede perder el cuaderno</p><ul><li>Es difícil buscar entradas antiguas</li><li>No se puede compartir fácilmente</li></ul><p><strong>Ideal para:</strong> Reflexiones diarias, notas inmediatamente posteriores al entrenamiento.</p><p><strong>Recomendación:</strong> Enfoque híbrido: papel para las entradas diarias, digital para los resúmenes y estadísticas mensuales.</p><hr><h2 id="sample-entries" tabindex="-1">Sample Entries <a class="header-anchor" href="#sample-entries" aria-label="Permalink to &quot;Sample Entries&quot;">​</a></h2><h3 id="example-good-training-entry" tabindex="-1">Example: Good Training Entry <a class="header-anchor" href="#example-good-training-entry" aria-label="Permalink to &quot;Example: Good Training Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 15, 2024 <strong>Duration:</strong> 90 minutes <strong>Location:</strong> Club terrain <strong>Terrain:</strong> Hard <strong>Weather:</strong> Sunny, light wind</p><p><strong>Today&#39;s Intention:</strong> Improve pointing accuracy at 8m</p><p><strong>Technical Practice:</strong></p><ul><li>Pointing at 8m: 30 attempts, 18 within 20cm (60%)</li><li>Noticed I&#39;m more accurate when I take 3 breaths before throwing</li><li>Struggled when wind picked up - need to adjust for wind better</li></ul><p><strong>What Worked Well:</strong></p><ol><li>Pre-shot routine was consistent</li><li>Stayed calm after misses</li><li>Adjusted grip for hard terrain</li></ol><p><strong>Key Insight:</strong> My accuracy drops when I rush. Slowing down by 2 seconds improves success rate significantly.</p><p><strong>Mental Game:</strong></p><ul><li>Energy: 8/10</li><li>Focus: 7/10</li><li>Used Inner Coach after 3 bad throws - helped me reset</li></ul><p><strong>Tomorrow&#39;s Focus:</strong> Practice pointing in windy conditions, maintain slow routine</p></details><h3 id="example-good-competition-entry" tabindex="-1">Example: Good Competition Entry <a class="header-anchor" href="#example-good-competition-entry" aria-label="Permalink to &quot;Example: Good Competition Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 20, 2024 <strong>Tournament:</strong> Regional Championship <strong>Format:</strong> Triples <strong>Final Placement:</strong> 5th of 16 teams</p><p><strong>Performance Analysis:</strong></p><ul><li>Technical: 7/10 - Pointing was solid, shooting was inconsistent</li><li>Mental: 8/10 - Stayed calm under pressure</li><li>Tactical: 6/10 - Made one bad decision in semi-final</li></ul><p><strong>Best Moment:</strong> Carreau in quarter-final to win 13-12</p><p><strong>Toughest Moment:</strong> Semi-final, 11-11, rushed a shot and missed badly</p><p><strong>Key Learning:</strong> When score is tight, I need to slow down even more, not speed up. My Inner Critic tried to take over (&quot;Don&#39;t mess this up!&quot;) but I caught it and used Inner Coach instead (&quot;You&#39;ve made this shot 100 times, trust your routine&quot;).</p><p><strong>For Next Competition:</strong> Practice pressure situations in training - simulate 11-11 scenarios</p></details><hr><h2 id="recursos-relacionados" tabindex="-1">Recursos relacionados <a class="header-anchor" href="#recursos-relacionados" aria-label="Permalink to &quot;Recursos relacionados&quot;">​</a></h2><ul><li><a href="/es/goal-template">Plantilla de establecimiento de objetivos</a> - Establezca y realice un seguimiento de sus objetivos de mejora</li><li><a href="/es/taller">Taller</a> - Sesiones grupales sobre juego mental y reflexión</li><li><a href="/es/sesion-de-formacion">Sesión de Formación</a> - Práctica estructurada con compañeros</li><li><a href="/es/education/fuerza-mental">Fuerza mental</a> - Desarrollar resiliencia mental</li><li><a href="/es/education/mindfulness">Mindfulness</a> - Desarrollar la conciencia y el enfoque</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to diary keeping? Start here:</strong></p><p><strong>Week 1:</strong> Use Quick Daily Entry (5 minutes after each session) <strong>Week 2:</strong> Add one reflection prompt per entry <strong>Week 3:</strong> Try full Daily Training Entry <strong>Week 4:</strong> Do first Weekly Summary</p><p><strong>After one month:</strong> Add Monthly Summary and specific practice logs</p><hr><div class="warning custom-block"><p class="custom-block-title">Errores comunes en el diario</p><ol><li><strong>Demasiado detallado</strong>: pasar 30 minutos escribiendo y luego dejarlo después de una semana.</li><li><strong>Demasiado vago</strong>: &quot;Entré hoy y estuvo bien&quot; no te ayuda a mejorar.</li><li><strong>Solo registra los fracasos</strong> - ¡Celebra también los triunfos!</li><li><strong>Nunca revisar</strong> - El poder está en leer entradas pasadas</li><li><strong>Esperar demasiado</strong> - Escribe dentro de los 30 minutos posteriores a la finalización.</li></ol></div><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Evernote</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Daily Training Entry Template</li><li>Competition/Match Entry Template</li><li>Weekly Summary Template</li></ol><hr><p><strong>Mejor momento:</strong></p><p><strong>Momento más difícil:</strong></p><p><strong>Cómo respondí:</strong></p><hr><h3 id="mental-game-in-competition" tabindex="-1">Mental Game in Competition <a class="header-anchor" href="#mental-game-in-competition" aria-label="Permalink to &quot;Mental Game in Competition&quot;">​</a></h3><p><strong>Pressure Situations:</strong></p><p><strong>How I Managed Pressure:</strong></p><p><strong>Inner Critic Activity (1-10):</strong> _____ <strong>Inner Coach Activity (1-10):</strong> _____</p><p><strong>Mental Techniques Used:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Routine Consistency</li><li>[ ] Other: ________</li></ul><hr><h3 id="aprendizajes-clave" tabindex="-1">Aprendizajes clave <a class="header-anchor" href="#aprendizajes-clave" aria-label="Permalink to &quot;Aprendizajes clave&quot;">​</a></h3><p><strong>Técnico:</strong></p><p><strong>Táctico:</strong></p><p><strong>Mental:</strong></p><p><strong>Para la próxima competición:</strong></p><hr><h2 id="weekly-summary-template" tabindex="-1">Weekly Summary Template <a class="header-anchor" href="#weekly-summary-template" aria-label="Permalink to &quot;Weekly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Semana de:</strong> ________</p><h3 id="descripcion-general-de-la-capacitacion" tabindex="-1">Descripción general de la capacitación <a class="header-anchor" href="#descripcion-general-de-la-capacitacion" aria-label="Permalink to &quot;Descripción general de la capacitación&quot;">​</a></h3><p><strong>Total de horas de capacitación:</strong> _____ <strong>Número de sesiones:</strong> _____ <strong>Horas de competencia:</strong> _____ <strong>Entrenamiento mental:</strong> _____ minutos <strong>Entrenamiento físico:</strong> _____ sesiones</p><h3 id="progreso-semanal" tabindex="-1">Progreso semanal <a class="header-anchor" href="#progreso-semanal" aria-label="Permalink to &quot;Progreso semanal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Área objetivo</th><th>Objetivo</th><th>Real</th><th>Progreso</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="victorias-de-esta-semana" tabindex="-1">Victorias de esta semana <a class="header-anchor" href="#victorias-de-esta-semana" aria-label="Permalink to &quot;Victorias de esta semana&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="desafios-de-esta-semana" tabindex="-1">Desafíos de esta semana <a class="header-anchor" href="#desafios-de-esta-semana" aria-label="Permalink to &quot;Desafíos de esta semana&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="reconocimiento-de-patrones" tabindex="-1">Reconocimiento de patrones <a class="header-anchor" href="#reconocimiento-de-patrones" aria-label="Permalink to &quot;Reconocimiento de patrones&quot;">​</a></h3><p>¿Qué patrones estoy notando en mi práctica/desempeño?</p><h3 id="enfoque-de-la-proxima-semana" tabindex="-1">Enfoque de la próxima semana <a class="header-anchor" href="#enfoque-de-la-proxima-semana" aria-label="Permalink to &quot;Enfoque de la próxima semana&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr>',195)])])}]]);export{o as __pageData,r as default};
